select jsonb_build_object('workflow_errors',(select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'created_at',a.created_at,'workflow',a.entity_id,'execution_id',a.after->>'execution_id','node',a.after->>'node','message',a.after->>'message','run_id',a.after->>'run_id') order by a.id),'[]'::jsonb) from ops.audit_log a where a.actor_type='n8n' and a.action='workflow_error' and a.created_at>='2026-10-27T16:01:20Z' and a.entity_id in ('WF-19','TsqSMa5MlO3QBLkt')),'unknown_rejections',(select count(*) from ops.audit_log a where a.action='apify_callback_rejected' and a.created_at>='2026-10-27T16:01:20Z'),'running_parents',(select count(*) from ops.scrape_runs where status='running'),'unprocessed_actors',(select count(*) from ops.apify_runs where processed_at is null)) as incremental_callback_security;
